<script setup lang="ts">
import {ref,computed} from 'vue'
import {ChevronDown,Check} from 'lucide-vue-next'
import type {Account} from '../sources/contracts'
import {useFileSourcesStore} from '@/stores/fileSources'
import {nativeCall} from '@/platform/native'
import AnchoredMenu from '../library/AnchoredMenu.vue'
const props=defineProps<{account:Account}>(),emit=defineEmits<{select:[id:string]}>(),sources=useFileSourcesStore()
const open=ref(false),position=ref({x:0,y:0}),expanded=ref(''),error=ref(''),lines=ref<Record<string,{primary:string;backupAddresses:Record<string,string>;selectedLineName:string}>>({})
const servers=computed(()=>sources.accounts.filter(a=>['jellyfin','emby','plex'].includes(a.providerId)))
async function show(event:MouseEvent){const box=(event.currentTarget as HTMLElement).getBoundingClientRect();position.value={x:box.right-240,y:box.bottom+4};open.value=!open.value;error.value='';if(!open.value)return;await Promise.all(servers.value.map(async account=>{try{const result=await nativeCall<{endpoints:typeof lines.value[string]}>('server_endpoints',{accountId:account.id,action:'get'});if(result?.endpoints)lines.value[account.id]=result.endpoints}catch(cause){error.value=(cause as Error).message}}))}
async function select(account:Account,name=''){try{const result=await nativeCall<{account:Account}>('server_endpoints',{accountId:account.id,action:'select',name});const index=sources.accounts.findIndex(a=>a.id===account.id);if(index>=0)sources.accounts[index]=result.account;open.value=false;emit('select',account.id)}catch(cause){error.value=(cause as Error).message}}
</script>
<template><button class="server-switch-trigger" @click="show"><span>{{account.name}} · {{lines[account.id]?.selectedLineName||'主地址'}}</span><ChevronDown :size="14"/></button><AnchoredMenu v-if="open" :x="position.x" :y="position.y" label="服务器" @close="open=false"><div class="server-switch-section-title">媒体服务器</div><template v-for="server in servers" :key="server.id"><button v-if="!Object.keys(lines[server.id]?.backupAddresses||{}).length" role="menuitem" @click="select(server)">{{server.name}}<Check v-if="server.id===account.id" :size="16"/></button><template v-else><button role="menuitem" :aria-expanded="expanded===server.id" @click="expanded=expanded===server.id?'':server.id">{{server.name}}<ChevronDown :size="14"/></button><div v-if="expanded===server.id" class="server-switch-lines"><button role="menuitem" @click="select(server)">主地址<Check v-if="server.id===account.id&&!lines[server.id]?.selectedLineName" :size="16"/></button><button v-for="(_,name) in lines[server.id]?.backupAddresses" :key="name" role="menuitem" @click="select(server,name)">{{name}}<Check v-if="server.id===account.id&&lines[server.id]?.selectedLineName===name" :size="16"/></button></div></template></template><p v-if="error" role="alert">{{error}}</p></AnchoredMenu></template>
<style scoped>.server-switch-trigger{display:flex;align-items:center;gap:10px;border:1px solid var(--border);border-radius:7px;padding:7px 12px;font-size:13px}.server-switch-section-title{padding:8px 10px;color:var(--muted-text);font-size:12px}.server-switch-lines{padding-left:14px}button{display:flex;align-items:center;justify-content:space-between;gap:12px}[role=alert]{color:#e35d5d}</style>
